import{_ as s,C as o,o as t,c as r,a2 as a,b as c,w as n,a as l,E as d,a3 as h}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse('{"title":"Licensing","description":"How NitroCord licensing works for buyers — where to buy, activation, hostname seats, offline grace, and what happens when the license server is unreachable.","frontmatter":{"title":"Licensing","description":"How NitroCord licensing works for buyers — where to buy, activation, hostname seats, offline grace, and what happens when the license server is unreachable."},"headers":[],"relativePath":"nitrocord/getting-started/licensing.md","filePath":"nitrocord/getting-started/licensing.md","lastUpdated":null}'),p={name:"nitrocord/getting-started/licensing.md"};function u(g,e,y,f,m,k){const i=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h1><p>NitroCord is a commercial product sold by PingLess Studios. One license key turns the same jar from the free community edition into the full protected proxy. This page covers everything you need to know as a buyer — no configuration beyond pasting one line.</p><h2 id="what-the-license-does" tabindex="-1">What the license does <a class="header-anchor" href="#what-the-license-does" aria-label="Permalink to &quot;What the license does&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Community edition (no key)</th><th>Licensed</th></tr></thead><tbody><tr><td>Proxy core</td><td>Full Velocity 4.1.0 behavior, all plugins work</td><td>Identical</td></tr><tr><td>Branding</td><td>NitroCord name and theme</td><td>Identical</td></tr><tr><td>Attack prevention</td><td><strong>Disabled</strong> — every check, the firewall, anti-bot, anti-VPN, packet scoring</td><td><strong>Fully active</strong></td></tr><tr><td><code>/nitrocord</code> admin command</td><td>Works</td><td>Works</td></tr></tbody></table><p>With an empty <code>license-key</code> the proxy runs exactly like stock Velocity with NitroCord branding, and the console reminds you at startup:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No license key set in nitrocord.toml; running the NitroCord community edition. Attack prevention is disabled - get a license at https://altis.host</span></span></code></pre></div><p>A valid key unlocks the entire protection engine: the kernel firewall, attack mode, rate limiting, anti-bot verification, GeoIP and anti-VPN blocking, packet flood scoring and the exploit filters.</p><h2 id="buying-a-license" tabindex="-1">Buying a license <a class="header-anchor" href="#buying-a-license" aria-label="Permalink to &quot;Buying a license&quot;">​</a></h2><p>Licenses are issued through the <strong>Altis dashboard</strong> at <a href="https://altis.host" target="_blank" rel="noreferrer">https://altis.host</a>. After purchase you receive a key in the format <code>PL-XXXX-...</code>, shown on your dashboard.</p><div class="warning custom-block"><p class="custom-block-title">Treat your key like a password</p><p>Anyone holding your key can consume your activation seats. Do not commit <code>nitrocord.toml</code> to a public repository, do not paste the key in support chats, and contact Altis to have a leaked key reissued.</p></div><h2 id="activation" tabindex="-1">Activation <a class="header-anchor" href="#activation" aria-label="Permalink to &quot;Activation&quot;">​</a></h2><ol><li><p>Open <code>nitrocord.toml</code> in your proxy run directory (generated on first start).</p></li><li><p>Paste the key:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">license-key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PL-XXXX-XXXX-XXXX-XXXX&quot;</span></span></code></pre></div></li><li><p><strong>Restart the proxy.</strong> The license is read at startup; editing the key requires a restart to take effect.</p></li></ol><p>Within a few seconds of the bind you should see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>License verified - thank you for supporting NitroCord.</span></span></code></pre></div><p>That single line means protection is live. From then on the proxy re-validates your key periodically in the background — you never have to touch it again, and the check never blocks startup or gameplay.</p><h2 id="seats-one-activation-per-server-hostname" tabindex="-1">Seats: one activation per server hostname <a class="header-anchor" href="#seats-one-activation-per-server-hostname" aria-label="Permalink to &quot;Seats: one activation per server hostname&quot;">​</a></h2><p>Each activation seat binds to the <strong>hostname of the machine</strong> the proxy runs on — not to an IP address, not to a hardware fingerprint.</p><ul><li>The number of seats is set by your purchase — check your key&#39;s seat count in the Altis dashboard.</li><li>Starting the same key on a machine with a <strong>different hostname consumes a new seat</strong>.</li><li>When all seats are used, extra servers are denied: they keep running as proxies, but their protection stays off (see <a href="#when-a-key-is-denied">denial states</a>).</li></ul><p>Changing the IP, moving datacenters or reinstalling the OS does <strong>not</strong> consume a new seat as long as the hostname stays the same.</p><h2 id="offline-grace" tabindex="-1">Offline grace <a class="header-anchor" href="#offline-grace" aria-label="Permalink to &quot;Offline grace&quot;">​</a></h2><p>NitroCord must never take your network down because a licensing server hiccups. After the first successful activation, the proxy keeps a signed validation cache on disk (<code>nitrocord/license.cache</code>).</p><ul><li>If the Altis license server is <strong>unreachable</strong> — maintenance, your firewall, a routing issue — protection simply keeps running on that cache.</li><li>Grace lasts <strong>up to 3 days</strong>, capped further by the offline allowance configured on your license, and never past the license&#39;s own expiry.</li><li>As soon as the license server is reachable again, the background check refreshes the cache silently. No admin action, no restart.</li></ul><div class="info custom-block"><p class="custom-block-title">The proxy never shuts down over licensing</p><p>Whatever the license state — denied, expired, unreachable with an exhausted cache — NitroCord keeps proxying players. The worst case is protection turning off and falling back to community-edition behavior, with a console warning every 30 minutes until it is resolved.</p></div><h2 id="when-a-key-is-denied" tabindex="-1">When a key is denied <a class="header-anchor" href="#when-a-key-is-denied" aria-label="Permalink to &quot;When a key is denied&quot;">​</a></h2><p>If the license platform reports a problem — <strong>expired</strong>, <strong>revoked</strong>, <strong>suspended</strong>, or <strong>seat limit reached</strong> — that proxy&#39;s protection disables itself:</p><ul><li>all protection checks, the firewall and the MOTD cache turn off (vanilla Velocity behavior is preserved exactly),</li><li>a warning naming the denial reason is logged, then a reminder every 30 minutes,</li><li>the stored offline cache is discarded, so the denial survives restarts until fixed.</li></ul><p>Fix the cause in your Altis dashboard (renew, unsuspend, free a seat) or enter a different key and restart — protection comes back at the next successful check, no reinstall needed.</p>',27)),(t(),c(h,null,{default:n(()=>[d(i,{id:"mermaid-196",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22Start%20with%20license-key%20set%22%5D%20--%3E%20B%7B%22License%20platform%20answer%22%7D%0A%20%20%20%20B%20--%3E%7C%22valid%22%7C%20C%5B%22Protection%20active%3Cbr%2F%3Ecache%20refreshed%22%5D%0A%20%20%20%20B%20--%3E%7C%22unreachable%22%7C%20D%7B%22Valid%20cache%20on%20disk%3F%22%7D%0A%20%20%20%20D%20--%3E%7C%22yes%22%7C%20E%5B%22Offline%20grace%3Cbr%2F%3Eprotection%20stays%20on%22%5D%0A%20%20%20%20D%20--%3E%7C%22no%20%2F%20expired%20cache%22%7C%20F%5B%22Protection%20off%3Cbr%2F%3Ewarning%20every%2030%20min%22%5D%0A%20%20%20%20B%20--%3E%7C%22denied%3A%20expired%2C%20revoked%2C%3Cbr%2F%3Esuspended%2C%20seat%20limit%22%7C%20F%0A%20%20%20%20C%20-.-%3E%7C%22periodic%20re-check%22%7C%20B%0A%20%20%20%20E%20-.-%3E%7C%22server%20reachable%20again%22%7C%20C%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>I am moving to a new host. Do I need a new license?</strong> No. Move the jar, your configs and your key — but a machine with a different hostname binds a <strong>new seat</strong>. If your key has one seat, free the old activation in the Altis dashboard (or let support do it) before starting on the new host.</p><p><strong>Can I run several proxies on one key?</strong> Only if your key has multiple seats. Every running NitroCord instance consumes one seat per machine hostname — a network of three proxies on three machines needs three seats.</p><p><strong>Does activation need internet access?</strong> Once, briefly. The first activation must reach the Altis license platform; after that the offline grace cache covers outages of up to 3 days (or your license&#39;s configured allowance, whichever is shorter).</p><p><strong>I edited the key but nothing changed.</strong> License keys are only read at startup. Restart the proxy after editing <code>license-key</code>; <code>/nitrocord reload</code> reloads protection settings but does not re-read the key.</p><p><strong>What happens if I let the license expire?</strong> The proxy keeps running and proxying players, protection turns off, and the console reminds you every 30 minutes. Renew in the dashboard and the next background check (or a restart) reactivates everything.</p><p><strong>Where can I see my seats and activations?</strong> In the Altis dashboard at <a href="https://altis.host" target="_blank" rel="noreferrer">https://altis.host</a>, next to your key.</p>',7))])}const w=s(p,[["render",u]]);export{v as __pageData,w as default};
